/* 03_gsmtap — the tap: everything a phone's stack hands to the host.
 *
 * One UDP listener that demultiplexes by GSMTAP type. It is the only view in the
 * toolkit that sees the same traffic the handset sees, rather than what a radio
 * could overhear.
 */
static GtkWidget *
gtap_build_live(AppState *state, const char *module_id,
                GtkWidget *status, GtkTextBuffer *out)
{
    GtkWidget *body;
    GtkWidget *outer = radio_view_shell("LIVE TAP",
        "Listen on the GSMTAP port and demultiplex by type. Nothing is decoded "
        "twice: a payload goes to the module that owns its format.", &body);
    GtkWidget *listen_body, *watch_body, *filter_body;
    GtkWidget *listen = verb_card("LISTEN FOR MESSAGES", &listen_body);
    GtkWidget *watch = verb_card("READ THE WATCHLIST", &watch_body);
    GtkWidget *filter = verb_card("FILTER THEM", &filter_body);

    {
        GtkWidget *res = result_rect_new(state, NULL);
        mod_card_begin(res);
        gtk_box_append(GTK_BOX(listen_body),
            mod_arg_row_prefilled(state, module_id, status, "Listen for messages",
                "--listen", "4729 30",
                "Port, then seconds. The answer is every message received with "
                "its type and the decoder that took it."));
        gtk_box_append(GTK_BOX(listen_body), res);
        gtk_box_append(GTK_BOX(listen_body),
            mod_arg_choices(state, module_id, status, "Other inputs", "",
                "Read a pcap instead of a socket, or a stream on stdin.",
                (const char *[]) { "--read capture.pcap", "--pipe 4729" },
                (const char *[]) { "Read a Pcap", "Read a Pipe" }, 2));
    }
    gtk_box_append(GTK_BOX(body), listen);

    {
        GtkWidget *res = result_rect_new(state, NULL);
        mod_card_begin(res);
        gtk_box_append(GTK_BOX(watch_body),
            mod_arg_choices(state, module_id, status, "Read the identities", "",
                "The identities seen, and the watchlist that turns a live tap into "
                "an alert when one of them appears.",
                (const char *[]) { "--identities-tsv", "--watchlist" },
                (const char *[]) { "Identities", "Watchlist" }, 2));
        gtk_box_append(GTK_BOX(watch_body), res);
    }
    gtk_box_append(GTK_BOX(body), watch);

    {
        GtkWidget *res = result_rect_new(state, NULL);
        mod_card_begin(res);
        gtk_box_append(GTK_BOX(filter_body),
            mod_arg_choices(state, module_id, status, "Narrow the stream", "",
                "The filters a tap needs when the whole stream is too much: one "
                "channel, uplink only, or a time window.",
                (const char *[]) { "--channel 0", "--uplink 1",
                                   "--since 0 --until 60", "--any-port 4729" },
                (const char *[]) { "Channel", "Uplink", "Time Window",
                                   "Any Port" }, 4));
        gtk_box_append(GTK_BOX(filter_body), res);
    }
    gtk_box_append(GTK_BOX(body), filter);
    mod_card_end();

    (void) out;
    return outer;
}

static GtkWidget *
gtap_build_header(AppState *state, const char *module_id,
                  GtkWidget *status, GtkTextBuffer *out)
{
    GtkWidget *body;
    GtkWidget *outer = radio_view_shell("READ A HEADER",
        "The GSMTAP header in front of every payload: what the capture claims "
        "about where the message came from.", &body);
    GtkWidget *parse_body, *build_body, *export_body;
    GtkWidget *parse = verb_card("READ THE STATE", &parse_body);
    GtkWidget *build = verb_card("BUILD ONE", &build_body);
    GtkWidget *export = verb_card("EXPORT THE SURVEY", &export_body);

    {
        GtkWidget *res = result_rect_new(state, NULL);
        mod_card_begin(res);
        gtk_box_append(GTK_BOX(parse_body),
            mod_arg_row(state, module_id, status, "Read a Header",
                "--parse-header", "hex",
                "A GSMTAP header as hex. The answer is the version, the type, the "
                "timeslot, the ARFCN and the signal level, which is what a "
                "downstream reader trusts without checking."));
        gtk_box_append(GTK_BOX(parse_body), res);
    }
    gtk_box_append(GTK_BOX(body), parse);

    {
        GtkWidget *res = result_rect_new(state, NULL);
        mod_card_begin(res);
        gtk_box_append(GTK_BOX(build_body),
            mod_arg_row_prefilled(state, module_id, status, "Build a Header",
                "--build-header", "1 0 0 128",
                "Type, timeslot, ARFCN and signal level. A header is a claim, and "
                "building one is how you find out what a reader will believe."));
        gtk_box_append(GTK_BOX(build_body), res);
    }
    gtk_box_append(GTK_BOX(body), build);

    /* The SCP03t layer, which is the one SGP.22 leaves to SGP.02: the segments
       above are opaque because this is where their contents are protected. */
    {
        GtkWidget *t_body;
        GtkWidget *t = verb_card("PROTECT A SEGMENT", &t_body);
        GtkWidget *res = result_rect_new(state, NULL);
        mod_card_begin(res);
        gtk_box_append(GTK_BOX(t_body),
            mod_arg_row_prefilled(state, module_id, status, "Build the TLVs",
                "--es8-scp03t",
                "--k-enc 000102030405060708090A0B0C0D0E0F "
                "--k-mac 101112131415161718191A1B1C1D1E1F "
                "--host-challenge 0011223344556677 "
                "--card-challenge 8899AABBCCDDEEFF --payload BF2401020304",
                "The key set, the two challenges, and a segment to protect. The "
                "answer is the 84/85/86 TLVs a profile package travels in, with the "
                "derived session keys and both cryptograms beside them."));
        gtk_box_append(GTK_BOX(t_body), res);
        gtk_box_append(GTK_BOX(body), t);
    }

    {
        GtkWidget *res = result_rect_new(state, NULL);
        mod_card_begin(res);
        gtk_box_append(GTK_BOX(export_body),
            mod_arg_choices(state, module_id, status, "Write it out", "",
                "A tap is more useful when its output can be handed on: a pcap "
                "for Wireshark, a TSV for a spreadsheet, or a forwarded stream.",
                (const char *[]) { "--export-pcap out.pcap", "--decode-tsv capture.pcap",
                                   "--forward 10.0.0.2:4729" },
                (const char *[]) { "Export a Pcap", "Decode a Capture",
                                   "Forward" }, 3));
        gtk_box_append(GTK_BOX(export_body), res);
    }
    gtk_box_append(GTK_BOX(body), export);
    mod_card_end();

    (void) out;
    return outer;
}

static ModuleSubmenuEntry gtap_entries[] = {
    { "Live tap", "dialog-information-symbolic", NULL, gtap_build_live },
    { "Header", "utilities-terminal-symbolic", NULL, gtap_build_header },
};
/* --------------------------------------------------------------------------
   04_tower_map — Tower Survey.
 *
 * Four views, cut by the question being asked rather than by verb: what the
 * receiver can hear, where it is, how the result leaves, and the one
 * destructive act. Three shapes of control, chosen per verb rather than by a
 * rule:
 *
 *   a survey needs a radio technology and a band   -> form row, hint under it
 *   gpsd needs a device                            -> form row, hint under it
 *   exporting is one act with a format choice      -> one row, one path, three
 *                                                     small buttons
 *   listing is not an act at all                   -> a list, refreshed
 *
 * The Export view is the reason this file exists: three identical full-width
 * pills reading "Export KML / Export CSV / Export GeoJSON" said nothing about
 * being one decision, and nothing about the destination they share.
   -------------------------------------------------------------------------- */

static GtkWidget *
tmap_build_overview(AppState *state, const char *module_id,
                    GtkWidget *status, GtkTextBuffer *out)
{
    GtkWidget *body;
    GtkWidget *outer = radio_view_shell("SURVEY THE CELLS",
        "One record per cell, with or without a position fix. The store is "
        "written only when a survey pass runs.", &body);
    GtkWidget *survey_body, *read_body;
    GtkWidget *survey = verb_card("RUN A SURVEY PASS", &survey_body);
    GtkWidget *read = verb_card("READ THE RECORDED POINTS", &read_body);

    {
        GtkWidget *res = result_rect_new(state, NULL);

        mod_card_begin(res);
    gtk_box_append(GTK_BOX(survey_body),
        mod_arg_row(state, module_id, status, "Start Survey",
            "--survey", "gsm GSM900", "Radio technology (gsm or lte), then a "
            "band for GSM. LTE takes a band list or nothing at all."));
        gtk_box_append(GTK_BOX(survey_body), res);
    }
    gtk_box_append(GTK_BOX(survey_body), fkit_note(
        "A pass records one point per cell it decodes. A cell received without a "
        "position fix is still recorded; it appears in the without-fix count of "
        "the next card rather than as an error."));
    gtk_box_append(GTK_BOX(body), survey);

    {
        GtkWidget *res = result_rect_new(state, NULL);

        mod_card_begin(res);
    gtk_box_append(GTK_BOX(read_body),
        mod_arg_row(state, module_id, status, "Read the Points",
            "--list-tsv", "", "Every recorded point, as stored."));
        gtk_box_append(GTK_BOX(read_body), res);
    }
    gtk_box_append(GTK_BOX(read_body),
        mod_arg_row(state, module_id, status, "Count the Points",
            "--history", "", "How many points have a fix, how many do not, and "
            "how many distinct cells they describe."));
    gtk_box_append(GTK_BOX(body), read);
    mod_card_end();

    (void) out;
    return outer;
}

