/* 4. The transmit half: a carrier, the BCH that makes it a cell, and the chain
      a catcher would have to complete. */
static GtkWidget *
uair_build_downlink(AppState *state, const char *module_id,
                    GtkWidget *status, GtkTextBuffer *out)
{
    GtkWidget *body;
    GtkWidget *outer = radio_view_shell("PRETEND TO BE A TOWER",
        "A WCDMA carrier built as samples, and the chain a 3G catcher would have "
        "to complete. No radio is keyed unless one answers.", &body);
    GtkWidget *card_body;
    GtkWidget *card;

    card = verb_card("BUILD A CARRIER", &card_body);
    {
        GtkWidget *res = result_rect_new(state, NULL);
        mod_card_begin(res);
        gtk_box_append(GTK_BOX(card_body),
            mod_arg_row_prefilled(state, module_id, status, "Build one",
                "--transmit", "2140",
                "The carrier in MHz, in a licensed band. Without a BCH the result "
                "says plainly that a handset can synchronise to the carrier and "
                "cannot read a cell from it."));
        gtk_box_append(GTK_BOX(card_body), res);
        mod_card_end();
    }
    gtk_box_append(GTK_BOX(body), card);

    card = verb_card("CARRY A MIB", &card_body);
    {
        GtkWidget *res = result_rect_new(state, NULL);
        mod_card_begin(res);
        gtk_box_append(GTK_BOX(card_body),
            mod_arg_row_prefilled(state, module_id, status, "Build with the BCH",
                "--transmit", "2140 --bch-hex 012345",
                "The same carrier carrying a 24-bit MIB through the whole TS 25.212 "
                "chain and onto the P-CCPCH. The answer changes from 'no' to "
                "'partly' when a BCH is carried."));
        gtk_box_append(GTK_BOX(card_body), res);
        mod_card_end();
    }
    gtk_box_append(GTK_BOX(body), card);

    card = verb_card("READ THE SYSTEM INFORMATION", &card_body);
    {
        GtkWidget *res = result_rect_new(state, NULL);
        mod_card_begin(res);
        gtk_box_append(GTK_BOX(card_body),
            mod_arg_choices(state, module_id, status, "Read the message",
                "A message to build, or the worked vectors", 
                "The blocks a camper reads before it can ask for anything. Each "
                "octet is held against pycrate's transcription of TS 25.331 and, "
                "where a dissector exists, against tshark over GSMTAP.",
                (const char *[]) { "--sib-vectors",
                                   "--build-sib sib3 --cell-id 0x1234567 --sib4",
                                   "--build-sib sib5",
                                   "--build-sib mib --value-tag 3" },
                (const char *[]) { "Vectors", "SIB3", "SIB5", "MIB" }, 4));
        gtk_box_append(GTK_BOX(card_body), res);
        mod_card_end();
    }
    gtk_box_append(GTK_BOX(body), card);

    card = verb_card("IDENTIFY THE CARD", &card_body);
    {
        GtkWidget *res = result_rect_new(state, NULL);
        mod_card_begin(res);
        gtk_box_append(GTK_BOX(card_body),
            mod_arg_choices(state, module_id, status, "Ask for",
                "Identity type", "The MM IDENTITY REQUEST a catcher sends once the "
                "connection is up. The message is four octets and asks the handset "
                "to state its identity in the clear.",
                (const char *[]) { "--catcher-identity",
                                   "--catcher-identity --identity imei",
                                   "--catcher-identity --identity tmsi" },
                (const char *[]) { "IMSI", "IMEI", "TMSI" }, 3));
        gtk_box_append(GTK_BOX(card_body), res);
        mod_card_end();
    }
    gtk_box_append(GTK_BOX(body), card);

    card = verb_card("READ THE CATCHER CHAIN", &card_body);
    {
        GtkWidget *res = result_rect_new(state, NULL);
        mod_card_begin(res);
        gtk_box_append(GTK_BOX(card_body),
            mod_arg_row(state, module_id, status, "Read the Chain",
                "--catcher-model", "",
                "Eight steps, each with the clause it comes from and whether this "
                "tree can perform it. The gaps are named, not hidden."));
        gtk_box_append(GTK_BOX(card_body), res);
        mod_card_end();
    }
    gtk_box_append(GTK_BOX(body), card);

    card = verb_card("REPLAY THE AUTHENTICATION", &card_body);
    {
        GtkWidget *res = result_rect_new(state, NULL);
        mod_card_begin(res);
        gtk_box_append(GTK_BOX(card_body),
            mod_arg_row_prefilled(state, module_id, status, "Replay it",
                "--catcher-auth",
                "00112233445566778899aabbccddeeff ffeeddccbbaa99887766554433221100",
                "The RAND first, then the AUTN, both 32 hex digits. A catcher does "
                "not break AKA: it re-sends an AUTHENTICATION REQUEST the real "
                "network sent once and takes the RES that follows. This holds no "
                "key and computes no MAC."));
        gtk_box_append(GTK_BOX(card_body), res);
        mod_card_end();
    }
    gtk_box_append(GTK_BOX(body), card);

    /* The wall a catcher hits is the handset's own AKA check. A replay clears it
       only for a RAND the handset has already seen; a fresh AUTN clears it for a
       handset holding that SIM, and computing one needs the key -- lawful only
       for a SIM you own. The primitive is checked against TS 35.208 set 1
       elsewhere in the tree, so this card spends no new claim: it shows the AUTN
       that set fixes, from that set's own key and RAND. */
    card = verb_card("PROVE A CARD FROM A KEY", &card_body);
    {
        GtkWidget *res = result_rect_new(state, NULL);
        mod_card_begin(res);
        /* The arguments carry flags, and a field full of flags puts a verb on
           screen. A choice row keeps them in argv where they belong and shows
           only the act. */
        gtk_box_append(GTK_BOX(card_body),
            mod_arg_choices(state, module_id, status, "Key material",
                "A worked set of key material, or your own in the same shape",
                "The subscriber key, the operator variant, the sequence number and "
                "the RAND. The AUTN that comes back is the one TS 35.208 test set 1 "
                "fixes, because the key and the RAND are that set's.",
                (const char *[]) {
                    "--catcher-auth --ki 465B5CE8B199B49FAA5F0A2EE238A6BC "
                    "--op CDC202D5123E20F62B6D676AC72CB318 "
                    "--sqn FF9BB4D0B607 --amf B9B9 "
                    "--rand 23553CBE9637A89D218AE64DAE47BF35" },
                (const char *[]) { "Compute the AUTN" }, 1));
        gtk_box_append(GTK_BOX(card_body), fkit_note(
            "The only card on this page that can start an exchange instead of "
            "replaying one, and only with a key you already hold. Against a SIM "
            "you do not own it is identity theft, not research."));
        gtk_box_append(GTK_BOX(card_body), res);
        mod_card_end();
    }
    gtk_box_append(GTK_BOX(body), card);

    /* The other direction. Everything above is what a network sends; this is
       what a handset sends back, which is the half a catcher needs to answer
       with. The request is the message that opens a connection, the preamble is
       what announces it on the RACH, and the message part is the slot structure
       that carries it. */
    card = verb_card("READ THE UPLINK", &card_body);
    {
        GtkWidget *res = result_rect_new(state, NULL);
        mod_card_begin(res);
        gtk_box_append(GTK_BOX(card_body), fkit_note(
            "What a handset sends. The request is built octet for octet; the "
            "preamble is 4096 chips at 3.84 Mcps; the message part is the slot "
            "structure, not a waveform."));
        gtk_box_append(GTK_BOX(card_body),
            mod_arg_choices(state, module_id, status, "Read one piece",
                "A piece to build, or the pinned uplink vectors",
                "The three things a handset sends, and what each answers with.",
                (const char *[]) { "--uplink request --tmsi 12345678",
                                   "--uplink prach --signature 3 --slot 2",
                                   "--uplink message-part --sf 64",
                                   "--uplink list" },
                (const char *[]) { "Request", "Preamble", "Message Part", "List" }, 4));
        gtk_box_append(GTK_BOX(card_body), res);
        mod_card_end();
    }
    gtk_box_append(GTK_BOX(body), card);

    (void) out;
    return outer;
}

