/* 09_lte_attach — LTE Attach Forge.
 *
 * The module builds and reads the messages an attach is made of. Two of them are
 * the interesting ones here: the request a handset sends, and the identity
 * request a network sends in the clear when it wants the IMSI.
 *
 * The previous table carried six controls for verbs the module does not
 * implement - decode-guti, encode-guti, nas-mac, build-attach-accept and two
 * more - each of which printed the usage banner and exited zero. They are gone
 * rather than styled: a button that does nothing is worse than a missing one.
 */
static GtkWidget *
latt_build_attach(AppState *state, const char *module_id,
                  GtkWidget *status, GtkTextBuffer *out)
{
    GtkWidget *body;
    GtkWidget *av_view = NULL;
    GtkWidget *av_col = answer_view_new(state, &av_view);
    GtkWidget *outer = radio_view_shell("HOW A HANDSET ATTACHES",
        "The request that starts a session, built byte for byte, and the same "
        "bytes read back as fields.", &body);
    GtkWidget *enc_body, *dec_body, *stack_body;
    GtkWidget *enc = verb_card("BUILD A REQUEST", &enc_body);
    GtkWidget *dec = verb_card("READ A MESSAGE", &dec_body);
    GtkWidget *stack = verb_card("READ THE UE STACK", &stack_body);

    {
        GtkWidget *res = result_rect_new(state, NULL);

        mod_card_begin_answer(av_view);
        gtk_box_append(GTK_BOX(enc_body),
            mod_arg_row_prefilled(state, module_id, status, "Build the Request",
                "--encode-attach", "310150123456789",
                "The subscriber identity. The answer is the NAS message as hex, "
                "with the plmn, the identity type and the TAC derived from it."));
            }
    gtk_box_append(GTK_BOX(body), enc);

    {
        GtkWidget *res = result_rect_new(state, NULL);

        mod_card_begin(res);
        gtk_box_append(GTK_BOX(dec_body),
            mod_arg_row_prefilled(state, module_id, status, "Read the Message",
                "--decode-nas", "0741E208090113100521436587F9",
                "The NAS message as hex. The security header decides how the "
                "rest is read: a plain message and a protected one do not share "
                "an offset."));
            }
    gtk_box_append(GTK_BOX(body), dec);

    {
        GtkWidget *res = result_rect_new(state, NULL);

        mod_card_begin(res);
        gtk_box_append(GTK_BOX(stack_body),
            mod_arg_row(state, module_id, status, "Read the Stack",
                "--ue-stack", "",
                "Which LTE UE stack this machine has, by name if it has none. "
                "A modem on a serial port counts, and is reported as such."));
            }
    gtk_box_append(GTK_BOX(body), stack);
    /* One answer surface for the whole page: every card's answer lands here,
       replaced on each run, so nothing grows a well under its own button. */
    gtk_box_append(GTK_BOX(body), av_col);

    (void) out;
    return outer;
}

static GtkWidget *
latt_build_identity(AppState *state, const char *module_id,
                    GtkWidget *status, GtkTextBuffer *out)
{
    GtkWidget *body;
    GtkWidget *av_view = NULL;
    GtkWidget *av_col = answer_view_new(state, &av_view);
    GtkWidget *outer = radio_view_shell("IDENTITY",
        "How a subscriber identity is coded on the wire, and the one request that "
        "makes a handset say it in the clear.", &body);
    GtkWidget *enc_body, *dec_body, *exp_body;
    GtkWidget *enc = verb_card("BUILD THE MESSAGE", &enc_body);
    GtkWidget *dec = verb_card("READ A MESSAGE", &dec_body);
    GtkWidget *exp = verb_card("READ WHAT IS EXPOSED", &exp_body);

    {
        GtkWidget *res = result_rect_new(state, NULL);

        mod_card_begin_answer(av_view);
        gtk_box_append(GTK_BOX(enc_body),
            mod_arg_row_prefilled(state, module_id, status, "Encode the Identity",
                "--imsi-encode", "310150123456789",
                "The IMSI as digits. The answer is the packed BCD and the EPS "
                "mobile identity that carries it, which is where a swapped "
                "half-octet shows."));
            }
    gtk_box_append(GTK_BOX(body), enc);

    {
        GtkWidget *res = result_rect_new(state, NULL);

        mod_card_begin(res);
        gtk_box_append(GTK_BOX(dec_body),
            mod_arg_row_prefilled(state, module_id, status, "Decode the Octets",
                "--imsi-decode", "08090113100521436587F9",
                "The identity as hex. IMSI, IMEI and GUTI share a length octet "
                "and nothing else, so the type decides the reading."));
            }
    gtk_box_append(GTK_BOX(body), dec);

    {
        GtkWidget *res = result_rect_new(state, NULL);

        mod_card_begin(res);
        gtk_box_append(GTK_BOX(exp_body),
            mod_arg_row_prefilled(state, module_id, status, "Check the Request",
                "--identity-exposure", "075301",
                "A plain-NAS IDENTITY REQUEST asking for the IMSI is the "
                "canonical exposure: the answer names the finding and its "
                "severity, and a protected request is reported as not exposed."));
            }
    gtk_box_append(GTK_BOX(exp_body), fkit_note(
        "The check reads the security header before the body. A protected "
        "request carries the same message type and means something different, "
        "which is why the security context is printed beside the finding."));
    gtk_box_append(GTK_BOX(body), exp);

    /* The temporary identity the network issued, and the moment it gets a
       name. A GUTI attach names nobody until the network asks; the binding is
       what turns the second attach into a resolved subscriber. */
    {
        GtkWidget *guti_body;
        GtkWidget *guti = verb_card("THE TEMPORARY IDENTITY", &guti_body);
        GtkWidget *res = result_rect_new(state, NULL);

        mod_card_begin(res);
        gtk_box_append(GTK_BOX(guti_body),
            mod_arg_row_prefilled(state, module_id, status, "Read a GUTI",
                "--guti-decode", "080BF600F110270F3735928559",
                "The identity as hex. The answer is the PLMN, the MME group "
                "and code, and the M-TMSI that names the context."));
        gtk_box_append(GTK_BOX(guti_body),
            mod_arg_row_prefilled(state, module_id, status, "Bind it to a Subscriber",
                "--guti-map", "080BF600F110270F3735928559 001010000000001",
                "The GUTI and the IMSI behind it, as the identity response "
                "supplied them. The binding is kept, one row per GUTI, and the "
                "attach count grows each time that context re-attaches."));
        gtk_box_append(GTK_BOX(guti_body), res);
        gtk_box_append(GTK_BOX(body), guti);
    }
    /* One answer surface for the whole page: every card's answer lands here,
       replaced on each run, so nothing grows a well under its own button. */
    gtk_box_append(GTK_BOX(body), av_col);

    (void) out;
    return outer;
}

/* The middle of an attach: the RRC message that carries the first NAS PDU, and
   the responder that keeps answering it. A handset that never gets this far
   hands over nothing, so this page is the door the identity work walks through.
   The responder page takes no input of its own: it reads UL/DL lines from the
   answer surface's companion console and holds its state in the tree. */
static GtkWidget *
latt_build_middle(AppState *state, const char *module_id,
                  GtkWidget *status, GtkTextBuffer *out)
{
    GtkWidget *body;
    GtkWidget *av_view = NULL;
    GtkWidget *av_col = answer_view_new(state, &av_view);
    GtkWidget *outer = radio_view_shell("THE MIDDLE OF AN ATTACH",
        "The UE's RRCConnectionSetupComplete carries its first NAS message, and "
        "the responder keeps the conversation alive long enough to read it.", &body);
    GtkWidget *build_body, *read_body, *respond_body;
    GtkWidget *build = verb_card("BUILD THE CONTAINER", &build_body);
    GtkWidget *read = verb_card("READ THE CONTAINER", &read_body);
    GtkWidget *respond = verb_card("HOLD THE CONVERSATION", &respond_body);

    {
        GtkWidget *res = result_rect_new(state, NULL);

        mod_card_begin_answer(av_view);
        gtk_box_append(GTK_BOX(build_body),
            mod_arg_row_prefilled(state, module_id, status, "Wrap the NAS Message",
                "--setup-complete", "0741E208090113100521436587F9",
                "An uplink NAS message as hex. The answer is the UL-DCCH "
                "container a handset sends on RRCConnectionSetupComplete, with "
                "the selected PLMN and the NAS inside it."));
            }
    gtk_box_append(GTK_BOX(body), build);

    {
        GtkWidget *res = result_rect_new(state, NULL);

        mod_card_begin(res);
        gtk_box_append(GTK_BOX(read_body),
            mod_arg_row_prefilled(state, module_id, status, "Read the Container",
                "--parse-setup-complete", "20001C0E83C410120200020200000001E2",
                "The container as hex. The answer names the PLMN, the NAS "
                "message type and, where the UE stated one, the identity it "
                "gave - which is the moment a subscriber names itself."));
            }
    gtk_box_append(GTK_BOX(body), read);

    {
        GtkWidget *res = result_rect_new(state, NULL);

        mod_card_begin(res);
        gtk_box_append(GTK_BOX(respond_body),
            mod_arg_row(state, module_id, status, "Answer the Attach",
                "--nas-responder", "",
                "Reads uplink NAS lines from stdin and answers with the "
                "network's next message, holding the state between them."));
            }
    gtk_box_append(GTK_BOX(respond_body), fkit_note(
        "The responder builds only what this tree can encode honestly: the "
        "identity request, the accept and the detach answer. Where a real "
        "network would continue into authentication, the answer names the "
        "message and why the bytes stop here."));
    gtk_box_append(GTK_BOX(body), respond);
    gtk_box_append(GTK_BOX(body), av_col);

    (void) out;
    return outer;
}

