/* SMPP: the Short Message Peer-to-Peer protocol an SMSC speaks to the outside
 * world. A different layer from the TPDU, with its own header — and the layer an
 * SMS-scam investigation usually starts from. */
static GtkWidget *
otasm_build_smpp(AppState *state, const char *module_id,
                 GtkWidget *status, GtkTextBuffer *out)
{
    GtkWidget *body;
    GtkWidget *outer = radio_view_shell("SMPP MESSAGES",
        "The protocol between an SMSC and the systems that feed it: a 16-octet "
        "header, then fields whose lengths are the header's claim.", &body);
    GtkWidget *build_body, *parse_body, *resp_body, *ref_body;
    GtkWidget *build = verb_card("BUILD A PDU", &build_body);
    GtkWidget *parse = verb_card("READ A PDU", &parse_body);
    GtkWidget *resp = verb_card("ANSWER ONE", &resp_body);
    GtkWidget *ref = verb_card("READ THE REFERENCE VALUES", &ref_body);

    {
        GtkWidget *res = result_rect_new(state, NULL);
        mod_card_begin(res);
        gtk_box_append(GTK_BOX(build_body),
            mod_arg_choices(state, module_id, status, "Name the operation", "",
                "A submit and a deliver differ only in direction; a bind "
                "transceiver is the session that carries both.",
                (const char *[]) { "--smpp-build submit_sm --src 15551234567 --dst 15559876543 --msg 48656c6c6f",
                                   "--smpp-build deliver_sm --src 15551234567 --dst 15559876543 --msg 48656c6c6f",
                                   "--smpp-build bind_transceiver --system-id smppclient1 --password password" },
                (const char *[]) { "Submit", "Deliver", "Bind" }, 3));
        gtk_box_append(GTK_BOX(build_body), res);
    }
    gtk_box_append(GTK_BOX(body), build);

    {
        GtkWidget *res = result_rect_new(state, NULL);
        mod_card_begin(res);
        gtk_box_append(GTK_BOX(parse_body),
            mod_arg_row_prefilled(state, module_id, status, "Read",
                "--smpp-parse", "0000003c00000004000000000000000100050031353535313233343536370001013135353539383736353433000000000000010000000548656c6c6f",
                "A PDU as hex. The answer walks the body field by field at the "
                "offset the standard puts it, and reports a length that disagrees "
                "with the header rather than reading past it."));
        gtk_box_append(GTK_BOX(parse_body), res);
    }
    gtk_box_append(GTK_BOX(body), parse);

    {
        GtkWidget *res = result_rect_new(state, NULL);
        mod_card_begin(res);
        gtk_box_append(GTK_BOX(resp_body),
            mod_arg_row_prefilled(state, module_id, status, "Answer",
                "--smpp-response", "0000003c0000000400000000000000010005003135353531323334353637",
                "A request. The response is derived - same sequence number, the "
                "response bit set - because a session that gets the sequence wrong "
                "hangs rather than fails."));
        gtk_box_append(GTK_BOX(resp_body), res);
    }
    gtk_box_append(GTK_BOX(body), resp);

    {
        GtkWidget *res = result_rect_new(state, NULL);
        mod_card_begin(res);
        gtk_box_append(GTK_BOX(ref_body),
            mod_arg_row_prefilled(state, module_id, status, "Name a Command",
                "--smpp-pdu", "submit_sm",
                "A command name or id. The answer is the name, the direction and "
                "whether a response is expected, which is how a session is "
                "reconstructed from a capture."));
        gtk_box_append(GTK_BOX(ref_body), res);
    }
    gtk_box_append(GTK_BOX(body), ref);
    mod_card_end();

    (void) out;
    return outer;
}


/* The one SMS path with no subscriber on this side: the SMSC authenticates the
 * ESME, not a card. Two rows -- one that stops before the socket, one that opens
 * it -- so the octets can be read before a session exists. */
static GtkWidget *
otasm_build_send(AppState *state, const char *module_id,
                 GtkWidget *status, GtkTextBuffer *out)
{
    GtkWidget *body;
    GtkWidget *outer = radio_view_shell("SEND IT",
        "An SMSC accepts a submit from an ESME that binds with an identity and a "
        "password. No SIM is in that exchange, which is the whole point of the "
        "row.", &body);
    GtkWidget *dry_body, *live_body;
    GtkWidget *dry = verb_card("BUILD IT, SEND NOTHING", &dry_body);
    GtkWidget *live = verb_card("BIND, THEN SUBMIT", &live_body);

    {
        GtkWidget *res = result_rect_new(state, NULL);
        mod_card_begin(res);
        gtk_box_append(GTK_BOX(dry_body),
            mod_arg_row_prefilled(state, module_id, status, "Build",
                "--smpp-send", "--host 127.0.0.1 --dst 15559876543 --text hello --dry-run",
                "--dry-run stops before the socket, so the submit_sm octets and "
                "their length field can be read on their own."));
        gtk_box_append(GTK_BOX(dry_body), res);
    }
    gtk_box_append(GTK_BOX(body), dry);

    {
        GtkWidget *res = result_rect_new(state, NULL);
        mod_card_begin(res);
        gtk_box_append(GTK_BOX(live_body),
            mod_arg_row_prefilled(state, module_id, status, "Send",
                "--smpp-send", "--host 127.0.0.1 --system-id esme1 --src 15551234567 --dst 15559876543 --text hello",
                "binds, submits, then reads the response. Put the password in "
                "OTASM_SMPP_PASSWORD to keep it out of the process list."));
        gtk_box_append(GTK_BOX(live_body), res);
    }
    gtk_box_append(GTK_BOX(body), live);

    {
        GtkWidget *res = result_rect_new(state, NULL);
        mod_card_begin(res);
        gtk_box_append(GTK_BOX(live_body),
            mod_arg_row_prefilled(state, module_id, status, "Local stand-in",
                "--smpp-send", "--host 127.0.0.1 --port 2775 --src 15551234567 --dst 15559876543 --text hello",
                "no SMSC on the box? python3 tools/smpp_client.py --serve "
                "--port 2775 answers the bind and the submit and routes nothing, "
                "so the session can be read end to end offline."));
        gtk_box_append(GTK_BOX(live_body), res);
    }
    mod_card_end();

    /* The other transport: an HTTP gateway, where the SIM sits in a phone on
     * the account rather than in this machine. Same two-step shape -- build and
     * read, then send -- because the body is the thing worth inspecting. */
    {
        GtkWidget *http_body, *http_dev_body;
        GtkWidget *http = verb_card("SEND OVER A GATEWAY", &http_body);
        GtkWidget *http_dev = verb_card("WHICH PHONE SENDS", &http_dev_body);
        GtkWidget *res;

        res = result_rect_new(state, NULL);
        mod_card_begin(res);
        gtk_box_append(GTK_BOX(http_body),
            mod_arg_row_prefilled(state, module_id, status, "Build the request",
                "--http-send", "--dst 15559876543 --text hello --dry-run",
                "prints the URL, the header name and the exact JSON body the "
                "gateway expects, and sends nothing. The shape is textbee's "
                "SendSMSRequestDTO from its own openapi document."));
        gtk_box_append(GTK_BOX(http_body), res);

        res = result_rect_new(state, NULL);
        mod_card_begin(res);
        gtk_box_append(GTK_BOX(http_body),
            mod_arg_row_prefilled(state, module_id, status, "Send it",
                "--http-send", "--dst 15559876543 --text hello --device-id 64b7f0000000000000000002 --raw",
                "POSTs to the gateway. The key comes from OTASM_HTTP_KEY, not "
                "from a flag, because a flag is visible in the process list; "
                "--raw also echoes the body the gateway answered."));
        gtk_box_append(GTK_BOX(http_body), res);
        mod_card_end();
        gtk_box_append(GTK_BOX(body), http);

        res = result_rect_new(state, NULL);
        mod_card_begin(res);
        gtk_box_append(GTK_BOX(http_dev_body),
            mod_arg_row_prefilled(state, module_id, status, "List devices",
                "--http-devices", "--raw",
                "the phones this key can send from, with their SIM count and "
                "send tally, so --device-id is read rather than guessed."));
        gtk_box_append(GTK_BOX(http_dev_body), res);
        mod_card_end();
        gtk_box_append(GTK_BOX(body), http_dev);
    }

    (void) out;
    return outer;
}

